def sim(h,v0,ang,k,g=9.81,n=1,dt=0.002):
    th=np.radians(ang); x=0;y=h;vx=v0*np.cos(th);vy=v0*np.sin(th);t=0
    def acc(vx,vy):
        s=np.hypot(vx,vy); 
        return -k*s**(n)*vx, -g-k*s**(n)*vy
    while True:
        ax,ay=acc(vx,vy)
        # RK2
        vx2=vx+ax*dt/2; vy2=vy+ay*dt/2
        ax2,ay2=acc(vx2,vy2)
        xn=x+vx2*dt; yn=y+vy2*dt
        vxn=vx+ax2*dt; vyn=vy+ay2*dt
        if yn<=0:
            f=y/(y-yn); return t+f*dt, x+f*(xn-x), np.hypot(vx+f*(vxn-vx),vy+f*(vyn-vy))
        x,y,vx,vy,t=xn,yn,vxn,vyn,t+dt
